import{_ as a}from"./chunks/four-color-gates.B2VhumGU.js";import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.C7GIOALF.js";const p=JSON.parse('{"title":"Pile o’ Magic Commander","description":"","frontmatter":{},"headers":[],"relativePath":"formats/big-deck/pile-o-magic/commander.md","filePath":"formats/big-deck/pile-o-magic/commander.md","lastUpdated":null}'),n={name:"formats/big-deck/pile-o-magic/commander.md"};function l(s,e,d,h,m,c){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="pile-o-magic-commander" tabindex="-1">Pile o’ Magic Commander <a class="header-anchor" href="#pile-o-magic-commander" aria-label="Permalink to &quot;Pile o’ Magic Commander&quot;">​</a></h1><p><a href="./../">Big Deck versions</a> · <strong>Local rules: Commander version</strong></p><p>This page includes the shared-Pile rules and the Commander changes together. The ordinary <a href="./">Pile o&#39; Magic version</a> has a different copy-limit rule.</p><h2 id="setup-and-commander-changes" tabindex="-1">Setup and Commander changes <a class="header-anchor" href="#setup-and-commander-changes" aria-label="Permalink to &quot;Setup and Commander changes&quot;">​</a></h2><ul><li>Each player starts at <strong>40 life</strong> and has a command zone.</li><li>Use <strong>singleton</strong> Pile construction instead of Singlesome: one copy per card name, except explicit card exceptions and ordinary basic-land exceptions.</li><li>Use the shared Pile and its minimum size below instead of separate 100-card libraries.</li><li>Choose one of the commander-selection procedures at the end of this page before play.</li><li>Ignore the requirement that the shared Pile&#39;s cards match an individual commander&#39;s color identity.</li><li>Once selected, commanders otherwise behave normally: command-zone movement, commander tax, and 21 combat damage from a single commander still apply.</li><li>Draw seven-card opening hands from the shared Pile, use normal multiplayer setup, and take individual turns.</li></ul><h2 id="format-rule-changes" tabindex="-1">Format Rule Changes <a class="header-anchor" href="#format-rule-changes" aria-label="Permalink to &quot;Format Rule Changes&quot;">​</a></h2><p>Unless otherwise noted, all normal Magic: The Gathering rules apply.</p><h3 id="the-pile" tabindex="-1">The Pile <a class="header-anchor" href="#the-pile" aria-label="Permalink to &quot;The Pile&quot;">​</a></h3><p>Players all play out of a shared Library which is generally referred to as the Pile during construction or in format rules.</p><p>A pile may be formed in a few manners:</p><ul><li><em>Messy Pile</em>: Players all bring their own set of 45+ cards to shuffle into the Pile.</li><li><em>Themed Pile</em>: A Pile is constructed in advance (collaboratively or by a host) which adheres to a central theme, MTG Set, mechanical archetype, etc.</li></ul><h3 id="lands" tabindex="-1">Lands <a class="header-anchor" href="#lands" aria-label="Permalink to &quot;Lands&quot;">​</a></h3><p>Generally speaking, lands that only have mana abilities are not included in the Pile. Instead, we have included a classification of <em>Heap Lands</em> which is simply a list of Land cards Players will be able to retrieve from outside the game.</p><p>Once per turn, during their Upkeep, a player may place a card from their hand in the absolutely-removed-from-the-freaking-game-forever zone. That player then adds a <em>Heap Land</em> from outside the game to their hand. The chosen <em>Heap Land</em> must be able to produce mana of each color in the removed card’s Color Identity; it must not be able to produce mana of any additional colors.</p><p>This mechanic may be streamlined in practice to simply putting the card in a designated “land area” with the understanding that it now represents the specified land. Many players will prefer this over having a separate pile of lands outside the game.</p><p>Valid <em>Heap Lands</em> are defined below in the <em>Pile Composition</em> section.</p><h3 id="zones" tabindex="-1">Zones <a class="header-anchor" href="#zones" aria-label="Permalink to &quot;Zones&quot;">​</a></h3><p>Players share a Library and an absolutely-removed-from-the-freaking-game-forever zone. Other zones (graveyard, exile, etc) are not shared.</p><p>This may lead to interesting strategies around milling, recursion, and so on. Such unexpected effects are fine and shouldn’t be concerning unless they begin to lessen the fun for players.</p><h2 id="pile-composition" tabindex="-1">Pile Composition <a class="header-anchor" href="#pile-composition" aria-label="Permalink to &quot;Pile Composition&quot;">​</a></h2><h3 id="card-count" tabindex="-1">Card Count <a class="header-anchor" href="#card-count" aria-label="Permalink to &quot;Card Count&quot;">​</a></h3><p>For maximum madness, the traditional deck size is ~300 cards. However, <em>Themed Piles</em> may benefit from smaller card pools. The minimum Pile size is 45x(number of players).</p><h3 id="heap-lands" tabindex="-1">Heap Lands <a class="header-anchor" href="#heap-lands" aria-label="Permalink to &quot;Heap Lands&quot;">​</a></h3><p>The following Land cards are considered valid <em>Heap Land</em>s which can be retrieved from outside the game in accordance with the rules.</p><ul><li>Basic Lands: Plains, Island, Swamp, Mountain, Forest, Wastes</li><li>Dual-Color Lands <ul><li>Generic: Meandering River, Submerged Boneyard, Cinder Barrens, Timber Gorge, Tranquil Expanse, Forsaken Sanctuary, Foul Orchard, Woodland Stream, Highland Lake, Stone Quarry</li><li>Dual-Types: Idyllic Beachfront, Contaminated Aquifer, Geothermal Bog, Wooded Ridgeline, Radiant Grove, Sunlit Marsh, Haunted Mire, Tangled Islet, Molten Tributary, Sacred Peaks</li></ul></li><li>Tri-Color Lands: Seaside Citadel, Arcane Sanctum, Crumbling Necropolis, Savage Lands, Jungle Shrine, Nomad Outpost, Frontier Bivouac, Sandsteppe Citadel, Mystic Monastery, Opulent Palace</li><li>Five-Color Land: Transguild Promenade</li></ul><p>Four-Color Lands? Unfortunately, there are no straightforward four-color lands. Feel free to make some up (I like <a href="https://www.reddit.com/r/custommagic/comments/15b4j4c/a_cycle_of_fourcolor_lands/" target="_blank" rel="noreferrer">these Gates</a> by <a href="https://www.reddit.com/user/TerryTags/" target="_blank" rel="noreferrer">Reddit user TerryTags</a>). Or maybe allow four color cards to retrieve a Transguild Promenade. Decide together. These cards aren’t very common– it won’t come up much.</p><h3 id="sleeves" tabindex="-1">Sleeves <a class="header-anchor" href="#sleeves" aria-label="Permalink to &quot;Sleeves&quot;">​</a></h3><p>When playing with a <em>Messy Pile</em>, should Players avoid sleeving their cards to prevent opponents gaining insight on the content of their hands? Should all Players re-sleeve their cards to one shared color/style?</p><p>In short: no. Players should still sleeve their cards (with unique sleeves!) so that ownership is easy to establish at the end of the game.</p><p>Will the sleeves potentially present information to your opponents? Yeah, sometimes. It is a consequence of the format, but not one that often impacts the fun.</p><h2 id="disallowed-cards" tabindex="-1">Disallowed Cards <a class="header-anchor" href="#disallowed-cards" aria-label="Permalink to &quot;Disallowed Cards&quot;">​</a></h2><h3 id="tutors" tabindex="-1">Tutors <a class="header-anchor" href="#tutors" aria-label="Permalink to &quot;Tutors&quot;">​</a></h3><p>Tutoring is generally against the “play what you find” spirit of Pile o’ Magic. They should be discouraged for the sole reason that t<em>hey will take an inordinate amount of time to resolve</em>. (The deck is enormous and players won’t know all the cards if you’ve built a <em>Messy Pile</em>*.)</p><p>This isn’t a true “ban” on the card type. Total bans would prevent funny cards like <strong>Booster Tutor</strong> which don’t have the same issues. Just consider carefully before including any tutors– will they truly add to the fun?</p><p>Addendum: For cards like <strong>Tempest Hawk</strong> you could consider just having a separate pile of fetchable Tempest Hawks set aside, though no formalized rules or considerations have been made for this concept. Talk to your group.</p><h2 id="rules-clarifications" tabindex="-1">Rules Clarifications <a class="header-anchor" href="#rules-clarifications" aria-label="Permalink to &quot;Rules Clarifications&quot;">​</a></h2><h3 id="the-absolutely-removed-from-the-freaking-game-forever-zone" tabindex="-1">The Absolutely-removed-from-the-freaking-game-forever Zone <a class="header-anchor" href="#the-absolutely-removed-from-the-freaking-game-forever-zone" aria-label="Permalink to &quot;The Absolutely-removed-from-the-freaking-game-forever Zone&quot;">​</a></h3><p>Cards in the ARFTFGF Zone are outside “Outside The Game”- they cannot be played by cards like <strong>Wish</strong>. (<a href="https://markrosewater.tumblr.com/post/146325356493/i-get-that-a-card-removed-from-the-game-for" target="_blank" rel="noreferrer">https://markrosewater.tumblr.com/post/146325356493/i-get-that-a-card-removed-from-the-game-for</a>)</p><p>Additionally, “Forever” only refers to the duration of the current game. (<a href="https://markrosewater.tumblr.com/post/50514158983/if-a-player-has-his-creature-hit-with-an-awol-can" target="_blank" rel="noreferrer">https://markrosewater.tumblr.com/post/50514158983/if-a-player-has-his-creature-hit-with-an-awol-can</a>)</p><h2 id="other-references" tabindex="-1">Other References <a class="header-anchor" href="#other-references" aria-label="Permalink to &quot;Other References&quot;">​</a></h2><h3 id="four-color-gates-by-reddit-user-terrytags" tabindex="-1">Four-Color Gates by Reddit User TerryTags <a class="header-anchor" href="#four-color-gates-by-reddit-user-terrytags" aria-label="Permalink to &quot;Four-Color Gates by Reddit User TerryTags&quot;">​</a></h3><p><img src="'+a+'" alt="Four-Color Gates by Reddit User TerryTags" loading="lazy"></p><p>Source: <a href="https://www.reddit.com/r/custommagic/comments/15b4j4c/a_cycle_of_fourcolor_lands/" target="_blank" rel="noreferrer">A cycle of four-color lands</a> by Reddit user TerryTags.</p><h2 id="commander-selection" tabindex="-1">Commander selection <a class="header-anchor" href="#commander-selection" aria-label="Permalink to &quot;Commander selection&quot;">​</a></h2><h3 id="let-the-pile-decide" tabindex="-1">Let the Pile decide. <a class="header-anchor" href="#let-the-pile-decide" aria-label="Permalink to &quot;Let the Pile decide.&quot;">​</a></h3><p>The first option we’ll examine is to find a Commander using the Pile. Prior to the game, each Player reveals cards from the top of the Pile until they reveal a Creature. That Creature becomes their Commander and is moved to the Command Zone. You may also limit this to the first <em>Legendary</em> Creature they reveal (or whatever restrictions you like).</p><p>The Creature revealed may not (likely will not) match the Color Identity of the entire deck, which is usually a requirement when building a Commander deck. For “Pile o’ Magic: Commander” we will ignore this requirement. During play, the Commander otherwise behaves as normal.</p><h3 id="bring-your-own" tabindex="-1">Bring your own. <a class="header-anchor" href="#bring-your-own" aria-label="Permalink to &quot;Bring your own.&quot;">​</a></h3><p>Option number 2 is to just bring your own Commander! Each Player brings a 5-color Legendary Creature (separate from any cards being contributed to a <em>Messy Pile</em>) which will serve as their Commander.</p><p>Try to avoid bringing Commanders with tutor-like effects. They enable Players of <em>Messy Piles</em> to focus more on their own card contributions. The Players should be focused on playing into the unpredictable card pool of Pile o’ Magic.</p><h3 id="deal-em" tabindex="-1">Deal ‘em. <a class="header-anchor" href="#deal-em" aria-label="Permalink to &quot;Deal ‘em.&quot;">​</a></h3><p>Now onto Option 3: each Player brings 3 Legendary Creatures which may serve as a Commander (disregard Color Identity). All of these creatures are shuffled together.</p><p>Each Player is dealt 3 random Commander candidates, they then choose the Commander they like (or think they can use) best. The remaining Commander candidates can be kept out of the game or shuffled into the Pile.</p><h3 id="what-specific-commanders-are-good-for-this-format" tabindex="-1">What <em>specific</em> Commanders are good for this format? <a class="header-anchor" href="#what-specific-commanders-are-good-for-this-format" aria-label="Permalink to &quot;What *specific* Commanders are good for this format?&quot;">​</a></h3><p>Fear not: I have opinions!</p><p>Tribals don’t work well because unless you’re playing a specific creature-type themed Pile, you won’t reliably be able to use tribal effects.</p><p>Commanders which tutor or search for specific categories are going to slow play tremendously and may suffer similar issues as tribals.</p><p>Commanders which generically enhance other cards, gain strength themselves, or get value out of mana or spells are going to work nicely. Whatever the Pile provides, you’ll utilize it!</p><table tabindex="0"><thead><tr><th style="text-align:left;">Commanders in Pile o’ Magic</th><th style="text-align:left;"></th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Commander</strong></td><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;"><strong>Why</strong></td></tr><tr><td style="text-align:left;">The Ur-Dragon</td><td style="text-align:left;">Bad</td><td style="text-align:left;">Tribal</td></tr><tr><td style="text-align:left;">Jodah, The Unifier</td><td style="text-align:left;">Bad</td><td style="text-align:left;">Search</td></tr><tr><td style="text-align:left;">Tiamat</td><td style="text-align:left;">Bad</td><td style="text-align:left;">A <em>Tribal Search</em>– oof.</td></tr><tr><td style="text-align:left;">Kenrith, the Returned King</td><td style="text-align:left;">Good</td><td style="text-align:left;">Generic “good” effects, value from mana</td></tr><tr><td style="text-align:left;">Omnath, Locus of All</td><td style="text-align:left;">Good</td><td style="text-align:left;">Value from mana</td></tr><tr><td style="text-align:left;">Ramos, Dragon Engine</td><td style="text-align:left;">Good</td><td style="text-align:left;">Self-empowerment, mana generation</td></tr><tr><td style="text-align:left;">Jodah, Archmage Eternal</td><td style="text-align:left;">Good</td><td style="text-align:left;">Generic spell reduction</td></tr></tbody></table><h2 id="local-rules-still-needing-decisions" tabindex="-1">Local rules still needing decisions <a class="header-anchor" href="#local-rules-still-needing-decisions" aria-label="Permalink to &quot;Local rules still needing decisions&quot;">​</a></h2><p>The shared-library ownership, leaving-the-game, simultaneous-draw, mulligan, and Heap Land timing questions from <a href="./#local-rules-still-needing-decisions">ordinary Pile o&#39; Magic</a> remain unresolved here.</p><p>The Pile-selection method also needs a destination for revealed non-commander cards. The recorded selection procedure does not say whether they return to the Pile, go to its bottom, or are shuffled back. Decide this before selecting commanders; do not silently discard those cards.</p>',62)])])}const g=t(n,[["render",l]]);export{p as __pageData,g as default};
